/// The new-side lines of one file's section of a diff, with their line
/// numbers: context and added lines of every `@@` hunk.
fn new_side_lines(section: &str) -> Vec<(u32, &str)> {
    let mut out = Vec::new();
    let mut next: Option<u32> = None;
    for line in section.lines() {
        if let Some(header) = line.strip_prefix("@@ ") {
            next = hunk_new_start(header);
            continue;
        }
        let Some(n) = next else { continue };
        if let Some(code) = line.strip_prefix('+') {
            if line.starts_with("+++ ") {
                continue;
            }

fn indent_code(code: &str, indent: &str) -> String {
    let mut out = String::new();
    for line in code.lines() {
        out.push_str(indent);
        out.push_str(line);
        out.push('\n');
    }
    out
}

#[derive(Serialize, Deserialize, Default, Debug)]
enum Kind { #[default] Private, Shared }
#[derive(Serialize, Deserialize, Debug)]
struct Note {
    text: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    link: Option<String>,
    #[serde(default)]
    kind: Kind,
}
fn main() {
    let old = r#"{"text":"hi"}"#;
    let n: Note = serde_json::from_str(old).unwrap();
    println!("{}", serde_json::to_string(&n).unwrap());
}
